// C++23: g++ -std=c++23 (GCC 12+)
#include <expected>
#include <iostream>

std::expected<int, int> f() { return -1; }
std::expected<int, int> g() { return std::unexpected(-1); }

int main() {
    std::cout << f().has_value() << ' ' << *f() << '\n';
    std::cout << g().has_value() << ' ' << g().error() << '\n';
