#include <optional>
#include <string>

std::optional<std::string> load_name(int id) {
    if (id == 1) return std::string("a-rather-long-instrument-name-0001");
    return std::nullopt;
}

int main() {
    auto name = load_name(1);                        // keep the optional alive
    if (name) std::cout << name->size() << ' ' << *name << '\n';
}
```
