#include <optional>

struct Limits {
    const int max_qty;
};

int main() {
    std::optional<Limits> lim;
    lim.emplace(Limits{100});
    lim.emplace(Limits{200});
    std::cout << lim->max_qty << '\n';   // 200
}
```

