    std::vector<std::unique_ptr<ShapeBase>> b;
    b.push_back(std::make_unique<CircleV>(1));
    b.push_back(std::make_unique<RectV>(2, 3));

    double sa = 0, sb = 0;
    for (const auto& s : a) sa += area(s);
    for (const auto& s : b) sb += s->area();
