struct Event {
    long time;
    long seq;              // tie-breaker: insertion order
    std::string name;
};

struct Later {             // "a has lower priority than b"
    bool operator()(const Event& a, const Event& b) const {
        if (a.time != b.time) return a.time > b.time;
        return a.seq > b.seq;
    }
};

