    names[{0, 0}] = "origin";
    names[{2, 3}] = "target";
    std::cout << names.at({2, 3}) << '\n';

    std::unordered_map<std::pair<int, int>, double, PairHash> cost;
    cost[{1, 2}] = 0.5;
    std::cout << cost.count({1, 2}) << ' ' << cost.count({2, 1}) << '\n';
