#include <type_traits>

constexpr int checksum_mode() {
    if (std::is_constant_evaluated()) {
        return 1;
    } else {
        return 2;
    }
}

int main() {
    constexpr int at_compile_time = checksum_mode();
    int at_run_time = checksum_mode();
    std::cout << at_compile_time << ' ' << at_run_time << '\n';   // 1 2
}
```

