    int s = 0;
    for (int i = 5 - k; i < 5; ++i) s += a[i];
    return s;
}

constexpr std::array<int, 5> fills{10, 20, 30, 40, 50};
static_assert(sum_last(fills, 2) == 90);

int main() {
    std::printf("%d\n", sum_last(fills, 2));   // 90
}
```

